import{_ as i}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as d,D as s,o as t,c as n,I as _,w as h,k as c,a as u,R as p,b as m,e as v}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const A=JSON.parse('{"title":"开发环境与第一个 Java 程序","description":"配置 JDK、理解源码到字节码的流程，并完成第一个可运行的 Java 程序。","frontmatter":{"title":"开发环境与第一个 Java 程序","date":"2026-09-22T00:00:00.000Z","category":"Java系统补习","tags":["Java","JDK","入门"],"description":"配置 JDK、理解源码到字节码的流程，并完成第一个可运行的 Java 程序。"},"headers":[],"relativePath":"courses/java/01-Java基础/01-开发环境与第一个程序.md","filePath":"courses/java/01-Java基础/01-开发环境与第一个程序.md","lastUpdated":1790079096000}'),J={name:"courses/java/01-Java基础/01-开发环境与第一个程序.md"},f=c("h1",{id:"开发环境与第一个-java-程序",tabindex:"-1"},[u("开发环境与第一个 Java 程序 "),c("a",{class:"header-anchor",href:"#开发环境与第一个-java-程序","aria-label":'Permalink to "开发环境与第一个 Java 程序"'},"​")],-1),b=p('<h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>区分 JDK、JRE、JVM 和 <code>java</code>、<code>javac</code>、<code>jar</code> 等命令。</li><li>能在命令行创建、编译、运行带包名的程序，并理解 classpath。</li><li>学会用 IDE 调试程序，同时保留命令行复现能力。</li></ul><h2 id="核心知识点" tabindex="-1">核心知识点 <a class="header-anchor" href="#核心知识点" aria-label="Permalink to &quot;核心知识点&quot;">​</a></h2><p>JDK 提供编译器、标准库和诊断工具，JVM 负责加载并执行字节码。推荐设置 <code>JAVA_HOME</code>，把 <code>bin</code> 加入 PATH；用 <code>java --version</code> 和 <code>javac --version</code> 检查版本。源码文件名通常与 public 类名一致，包名与目录层级对应。编译时 <code>javac -d out src/com/example/Main.java</code>，运行时用 <code>java -cp out com.example.Main</code>。模块化项目还会使用 <code>--module-path</code>。</p><h2 id="实践任务" tabindex="-1">实践任务 <a class="header-anchor" href="#实践任务" aria-label="Permalink to &quot;实践任务&quot;">​</a></h2><p>创建 <code>com.example.Main</code>，打印 JDK 版本、当前工作目录和一段问候语；再故意把类文件放到错误目录，观察包名与 classpath 不匹配时的错误。使用 IDE 设置断点，单步观察局部变量，并记录命令行等价操作。</p><h2 id="易错点" tabindex="-1">易错点 <a class="header-anchor" href="#易错点" aria-label="Permalink to &quot;易错点&quot;">​</a></h2><ul><li>把 JDK 安装目录和项目目录混为一谈，或只配置 IDE 而没有配置命令行环境。</li><li>用 <code>java Main</code> 运行带包名的类；运行参数应使用完全限定类名。</li><li>把源代码版本、编译目标版本和运行时版本混在一起，导致 <code>UnsupportedClassVersionError</code>。</li></ul><h2 id="复习清单" tabindex="-1">复习清单 <a class="header-anchor" href="#复习清单" aria-label="Permalink to &quot;复习清单&quot;">​</a></h2><ul><li>[ ] 能解释 JDK、JVM、字节码三者的关系。</li><li>[ ] 能独立完成源码、编译输出目录、classpath 的配置。</li><li>[ ] 能读懂找不到类、找不到主方法、版本不兼容三类错误。</li></ul>',10);function j(a,D,V,k,x,P){const r=i,l=s("ClientOnly");return t(),n("div",null,[f,_(l,null,{default:h(()=>{var e,o;return[(((e=a.$frontmatter)==null?void 0:e.aside)??!0)&&(((o=a.$frontmatter)==null?void 0:o.showArticleMetadata)??!0)?(t(),m(r,{key:0,article:a.$frontmatter},null,8,["article"])):v("",!0)]}),_:1}),b])}const C=d(J,[["render",j]]);export{A as __pageData,C as default};
